def search_insert(nums, target):
    lo, hi = 0, len(nums)
    while lo < hi:
        mid = (lo + hi) // 2
        if nums[mid] < target:
            lo = mid + 1               # answer is further right
        else:
            hi = mid                    # mid could be the answer
    return lo

